2763:     const sweep = Math.PI * 1.72;
2764:     ctx.save();
2765:     ctx.translate(s.x, s.y);
2766:     ctx.rotate(start);
2767:     for (let i = 0; i < count; i++) {
2768:       const t = i / (count - 1);
2769:       const a = t * sweep;
2770:       const intact = t < frac;
2771:       ctx.save();
2772:       ctx.rotate(a);
2773:       ctx.strokeStyle = intact ? (i % 3 === 0 ? '#9a7040' : '#6b4b2c') : 'rgba(77,55,33,0.35)';
