input.newString:
/* Menu */

.menu-screen {
  background:
    radial-gradient(ellipse at 72% 60%, transparent 0%, rgba(7, 11, 19, 0.15) 42%, rgba(7, 11, 19, 0.78) 100%),
    linear-gradient(180deg, rgba(7, 11, 19, 0.12) 0%, rgba(7, 11, 19, 0.18) 45%, rgba(7, 11, 19, 0.82) 100%);
}

.menu-chrome {
  position: absolute;
  top: calc(15px + var(--safe-top));
  right: calc(100px + var(--safe-right));
  left: calc(20px + var(--safe-left));
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 13px;
  color: rgba(199, 188, 170, 0.5);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.2em;
  pointer-events: none;
}

.menu-chrome-dots {
  display: flex;
  gap: 5px;
}

.menu-chrome-dots i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: rgba(239, 182, 97, 0.42);
}

.menu-chrome-dots i:nth-child(2) {
  background: rgba(213, 83, 63, 0.55);
}

.menu-chrome-dots i:nth-child(3) {
  background: rgba(129, 173, 137, 0.5);
}

.menu-chrome-status {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  color: rgba(213, 120, 99, 0.66);
  letter-spacing: 0.16em;
}

.menu-chrome-status i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #d5533f;
  box-shadow: 0 0 8px rgba(213, 83, 63, 0.8);
  animation: chipPulse 1.9s infinite;
}

.menu-window-btns {
  position: absolute;
  top: calc(9px + var(--safe-top));
  right: calc(14px + var(--safe-right));
  z-index: 5;
  display: flex;
  gap: 5px;
}

.window-btn {
  display: grid;
  width: 31px;
  height: 27px;
  padding: 0;
  place-items: center;
  border: 1px solid rgba(236, 219, 188, 0.2);
  border-radius: 3px;
  background: rgba(8, 13, 22, 0.72);
  color: rgba(199, 188, 170, 0.72);
  font-family: var(--sans);
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}

.window-btn:hover,
.window-btn:focus-visible {
  border-color: var(--gold);
  background: rgba(39, 34, 26, 0.92);
  color: var(--gold);
}

.window-btn.close:hover,
.window-btn.close:focus-visible {
  border-color: #d5533f;
  color: #f08b72;
}

.menu-screen.minimized {
  visibility: visible;
  background: none;
  pointer-events: none;
}

.menu-screen.minimized .menu-layout,
.menu-screen.minimized .menu-scrim,
.menu-screen.minimized .menu-chrome,
.menu-screen.minimized .menu-window-btns,
.menu-screen.minimized .menu-foot {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.menu-layout {
  transition: opacity 0.3s ease, visibility 0.3s;
}

.menu-dock {
  position: absolute;
  top: calc(12px + var(--safe-top));
  right: calc(14px + var(--safe-right));
  z-index: 48;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px 8px 9px;
  border: 1px solid rgba(239, 182, 97, 0.4);
  border-radius: 4px;
  background:
    linear-gradient(180deg, rgba(31, 36, 40, 0.94), rgba(8, 13, 21, 0.94));
  color: var(--bone);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  cursor: pointer;
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.46);
  pointer-events: auto;
  transition: border-color 0.2s, transform 0.2s, background 0.2s;
}

.menu-dock:hover,
.menu-dock:focus-visible {
  border-color: var(--gold);
  background:
    linear-gradient(180deg, rgba(52, 47, 36, 0.96), rgba(12, 17, 25, 0.96));
  transform: translateY(-1px);
}

.menu-dock.hidden {
  display: none;
}

.menu-dock .dock-mark {
  display: grid;
  width: 21px;
  height: 21px;
  place-items: center;
  border: 1px solid rgba(239, 182, 97, 0.34);
  border-radius: 2px;
  color: var(--gold);
  font-size: 11px;
}

.menu-dock i {
  padding-left: 8px;
  border-left: 1px solid rgba(236, 219, 188, 0.16);
  color: rgba(239, 182, 97, 0.6);
  font-size: 7px;
  font-style: normal;
  letter-spacing: 0.14em;
}

.scp-index {
  margin-bottom: 15px;
  padding-bottom: 13px;
  border-bottom: 1px solid rgba(239, 182, 97, 0.14);
}

.scp-index-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 8px;
  color: rgba(213, 83, 63, 0.78);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.22em;
}

.scp-index-head i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #d5533f;
  box-shadow: 0 0 6px rgba(213, 83, 63, 0.7);
}

.scp-entry {
  display: flex;
  gap: 7px;
  align-items: baseline;
  padding: 3px 0;
  color: rgba(199, 188, 170, 0.6);
  font-size: 8px;
  line-height: 1.35;
}

.scp-entry b {
  min-width: 55px;
  color: rgba(239, 182, 97, 0.84);
  font-size: 8px;
  letter-spacing: 0.05em;
}

.scp-entry span {
  color: rgba(199, 188, 170, 0.54);
  font-family: var(--serif);
  font-size: 9px;
  font-style: italic;
}

.menu-resume[hidden] {
  display: none;
}

