  const st = s.state;
  if (!st.owned || game.activeShelter !== s.id) {
    toast('NOT YOUR SHELTER', 'Claim it before you hide inside.', 'warn');
    Sound.deny();
    return;
  }
  if (st.integrity <= 0) {
